import{questionMarkup}from'./question-cues.js';
import{guardianPhase,guardianQuestion}from'./guardian-combat.js';
import{icon}from'./ui-icons.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ATTACK_TIPS={quake:'Shockwave · jump as the ring reaches you',beam:'Aimed strike · move sideways out of the marked lane',falls:'Falling stones · leave the marked circles',
 roots:'Root Eruption · step out of the cracking lines',seeds:'Seed Barrage · leave the circles; Cast clears thorn bushes',slam:'Canopy Slam · jump the shockwave',overgrowth:'Overgrowth · stand in a glowing blue patch',
 gale:'Gale Sweep · jump as the wind wall passes',volley:'Orbit Volley · keep moving',dive:'Sky Dive · get out of the circle, then jump the ring',twisters:'Twisters · run around them',
 prism:'Prism Beam · stand clear of the bouncing beam path',shards:'Shard Rain · leave the circles, then jump the bursts',cage:'Crystal Cage · escape through the blue gap',chain:'Storm Chain · jump it or run through the blue gap'};
export function guardianMessage(b){if(b.phase==='intro')return'The guardian awakens…';if(b.phase==='ward')return'A ward shields the guardian · answer to break it';if(b.phase==='finisher')return'Break the final three seals · correct answers stay';if(b.phase==='victory')return'The guardian yields. Arena restored.';if(b.phase==='recovery')return b.stagger?'Staggered! Cast now for a critical hit':'Core exposed · move within range and cast!';return ATTACK_TIPS[b.kind]||ATTACK_TIPS.quake;}
export function guardianHud(b,name,flash=''){return `<div class="guardian-hud"><div class="guardian-heading"><span>${esc(name)}</span><button data-do="retreat" aria-label="Save and return to sanctuary">${icon('close')}</button></div><div class="boss-health" role="meter" aria-label="Guardian health" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${b.bossHp}"><i style="width:${b.bossHp}%"></i></div><div class="guardian-health-note"><span>${b.bossHp}% · Phase ${guardianPhase(b)}</span><span>Your strength <b>${b.hp}</b></span></div><p id="guardian-callout" role="status"${flash?' class="flash"':''}>${esc(flash||guardianMessage(b))}</p></div>`;}
export function guardianFinisher(b,feedback=''){const current=guardianQuestion(b);if(!current?.q)return'';const{q,step,ward}=current,count=ward?2:3;return `<div class="guardian-finisher${ward?' guardian-ward':''}" aria-label="${ward?'English ward':'Final English seals'}"><div class="seal-count" aria-label="${step} of ${count} ${ward?'wards':'seals'} broken">${[...Array(count).keys()].map(i=>`<span class="${i<step?'broken':''}">${i<step?'✓':i+1}</span>`).join('')}</div><div class="finisher-question">${q.kind==='meaning'?`<span class="finisher-instruction">Connect its Turkish meaning</span>${esc(q.prompt)}`:q.kind==='definition'?`<span class="finisher-instruction">Which word matches?</span>${esc(q.prompt)}`:q.kind==='completion'?`<span class="finisher-instruction">Complete the inscription</span>${esc(q.prompt)}`:questionMarkup(q.prompt)}</div><div class="finisher-answers">${q.options.map((s,i)=>`<button type="button" data-do="guardian-answer" data-index="${i}" data-step="${step}"><span class="seal-symbol" aria-hidden="true">◇</span><span>${esc(s)}</span></button>`).join('')}</div><p class="finisher-feedback" role="status">${esc(feedback||'Read, then touch a rune. No reading timer.')}</p></div>`;}
export function guardianControls(){return `<div class="play-dock guardian-dock"><div class="joystick" id="joystick" aria-label="Move your creature"><div id="joystick-thumb"></div></div><button class="attack-button" id="attack-button" data-do="attack" aria-label="Cast your elemental attack">${icon('attack')}<small>Cast</small></button><button class="jump-button" id="jump-button" data-do="jump" aria-label="Jump over a shockwave">${icon('jump')}<small>Jump</small></button><div class="guardian-keyboard">WASD / arrows · Space jump · J / F cast</div></div>`;}
